(()=>{'use strict';const $=id=>document.getElementById(id);function show(data){const link=$('published-store-link');if(data.url){link.href=data.url;link.hidden=false;$('publish-status').textContent='Published · '+new Date(data.publishedAt).toLocaleString();}else{link.hidden=true;$('publish-status').textContent='Your storefront is not published.';}}
async function state(){try{const response=await fetch('/api/designer/storefront'),data=await response.json();if(!response.ok)throw Error(data.error);show(data);}catch(e){$('publish-status').textContent=e.message||'Publishing status unavailable.';}}
$('publish-store').onclick=async()=>{const button=$('publish-store');if(!window.designerCloudReady?.()){$('publish-status').textContent='Wait for Cloud saved before publishing.';return;}if(!confirm('Publish your saved designer profile and collection for everyone to see? Costs, supplier records and customers remain private.'))return;button.disabled=true;try{const response=await fetch('/api/designer/storefront',{method:'POST'}),data=await response.json();if(!response.ok)throw Error(data.error);show(data);}catch(e){$('publish-status').textContent=e.message||'Publishing failed.';}finally{button.disabled=false;}};
$('unpublish-store').onclick=async()=>{if(!confirm('Remove your public storefront? Your private collection and enquiries stay saved.'))return;try{const response=await fetch('/api/designer/storefront',{method:'DELETE'}),data=await response.json();if(!response.ok)throw Error(data.error);show({});}catch(e){$('publish-status').textContent=e.message;}};
$('load-enquiries').onclick=async()=>{const button=$('load-enquiries');button.disabled=true;try{const response=await fetch('/api/designer/enquiries'),data=await response.json();if(!response.ok)throw Error(data.error);const box=$('live-enquiries');box.replaceChildren();$('enquiry-status').textContent=data.enquiries.length+' real storefront enquiries received.';for(const e of data.enquiries){const card=document.createElement('article');card.className='record';for(const text of [e.name,e.product,e.contact,e.message,'Received: '+e.createdAt]){const p=document.createElement('p');p.textContent=text;card.append(p);}const add=document.createElement('button');add.textContent='Add to my sales flow';add.onclick=()=>{document.dispatchEvent(new CustomEvent('fashion-enquiry-import',{detail:e}));$('enquiry-status').textContent='Added to your sales flow. Check cloud save status.';add.disabled=true;};card.append(add);box.append(card);}}catch(e){$('enquiry-status').textContent=e.message||'Inbox unavailable.';}finally{button.disabled=false;}};state();})();
